// ⚙️ CONFIG — the only node you need to edit.
const config = {
  // Your Jira Cloud site. Must match the Jira credential.
  jiraBaseUrl: 'https://your-company.atlassian.net',

  // Test plans to turn into a test case. One per run.
  // Keep the label filter: it stops a plan getting two test cases.
  jql: 'project = QA AND issuetype = "Test Plan" AND status = Done AND (labels is EMPTY OR labels not in (ai-test-case-created, ai-test-case-failed)) ORDER BY updated ASC',

  // Where the steps go:
  //   'xray' → steps are added to an Xray Cloud "Test" issue (needs the Xray API key credential)
  //   'jira' → steps are written as a table in the issue description (no Xray needed)
  testManagement: 'xray',
  xrayBaseUrl: 'https://xray.cloud.getxray.app', // EU data residency: 'https://eu.xray.cloud.getxray.app'

  test: {
    projectKey: 'QA',
    issueType: 'Test',          // Xray "Test"; with testManagement 'jira' e.g. 'Task'
    summaryPrefix: '(e2e) ',
    linkType: 'Relates',        // link between the test and its test plan
    statusAfterCreate: '',      // e.g. 'Done'; '' = leave in the first status
  },

  // Also read issues linked to the test plan (e.g. the original requirement) as background.
  useLinkedIssues: true,

  // Write → check → review → fix loop. Total attempts before giving up (each costs 1-2 model calls).
  maxAttempts: 4,

  labels: {
    done: 'ai-test-case-created',   // added to the test plan on success
    failed: 'ai-test-case-failed',  // added to the test plan when no attempt passed
  },

  model: 'gpt-5.5',
};

// Manual test on one test plan: set a key here, then press "Test workflow". Ignored on scheduled runs.
const testIssueKey = '';
config.searchJql = $('▶ Test run').isExecuted && testIssueKey ? `key = ${testIssueKey}` : config.jql;
return [{ json: config }];

// ---- helpers ----
function adfToText(node) {
  // Jira Cloud (API v3) returns rich text as ADF. This turns it into plain text an LLM can read.
  if (node == null) return '';
  if (typeof node === 'string') return node;
  if (Array.isArray(node)) return node.map(adfToText).join('');
  switch (node.type) {
    case 'text': {
      const link = (node.marks || []).find((m) => m.type === 'link');
      const href = link?.attrs?.href;
      return href && href !== node.text ? `${node.text} (${href})` : (node.text || '');
    }
    case 'hardBreak': return '\n';
    case 'mention': return node.attrs?.text || '@user';
    case 'emoji': return node.attrs?.text || '';
    case 'inlineCard':
    case 'blockCard': return node.attrs?.url || '';
    case 'media': return '[attachment]';
    case 'paragraph':
    case 'heading': return adfToText(node.content) + '\n';
    case 'listItem': return '- ' + adfToText(node.content).trim() + '\n';
    case 'bulletList':
    case 'orderedList': return adfToText(node.content) + '\n';
    case 'tableRow': return '| ' + (node.content || []).map((c) => adfToText(c.content).trim().replace(/\n+/g, ' ')).join(' | ') + ' |\n';
    case 'codeBlock': return '```\n' + adfToText(node.content) + '\n```\n';
    case 'rule': return '---\n';
    default: return adfToText(node.content);
  }
}
// ---- end helpers ----

const cfg = $('⚙️ Config').first().json;
const issue = ($input.first().json.issues || [])[0];
if (!issue) return []; // nothing to do this run
const f = issue.fields || {};
const planText = adfToText(f.description).trim();

// Count the rows of a "Test Name" coverage table, if the plan has one.
let expectedSections = 0;
const lines = planText.split('\n').map((l) => l.trim());
const headerAt = lines.findIndex((l) => /^\|\s*test name\s*\|/i.test(l));
if (headerAt >= 0) {
  for (let i = headerAt + 1; i < lines.length && lines[i].startsWith('|'); i++) expectedSections++;
}

const linkedKeys = cfg.useLinkedIssues
  ? (f.issuelinks || []).map((l) => (l.inwardIssue || l.outwardIssue)?.key).filter(Boolean)
  : [];

return [{
  json: {
    key: issue.key,
    id: issue.id,
    summary: f.summary || '',
    planText: planText || '(empty test plan)',
    expectedSections,
    linkedKeys: [...new Set(linkedKeys)].slice(0, 5),
  },
}];

// ---- helpers ----
function adfToText(node) {
  // Jira Cloud (API v3) returns rich text as ADF. This turns it into plain text an LLM can read.
  if (node == null) return '';
  if (typeof node === 'string') return node;
  if (Array.isArray(node)) return node.map(adfToText).join('');
  switch (node.type) {
    case 'text': {
      const link = (node.marks || []).find((m) => m.type === 'link');
      const href = link?.attrs?.href;
      return href && href !== node.text ? `${node.text} (${href})` : (node.text || '');
    }
    case 'hardBreak': return '\n';
    case 'mention': return node.attrs?.text || '@user';
    case 'emoji': return node.attrs?.text || '';
    case 'inlineCard':
    case 'blockCard': return node.attrs?.url || '';
    case 'media': return '[attachment]';
    case 'paragraph':
    case 'heading': return adfToText(node.content) + '\n';
    case 'listItem': return '- ' + adfToText(node.content).trim() + '\n';
    case 'bulletList':
    case 'orderedList': return adfToText(node.content) + '\n';
    case 'tableRow': return '| ' + (node.content || []).map((c) => adfToText(c.content).trim().replace(/\n+/g, ' ')).join(' | ') + ' |\n';
    case 'codeBlock': return '```\n' + adfToText(node.content) + '\n```\n';
    case 'rule': return '---\n';
    default: return adfToText(node.content);
  }
}
// ---- end helpers ----

const plan = $('Prepare test plan').first().json;
const issues = $input.first().json.issues || [];
const background = issues
  .filter((i) => !/^test/i.test(i.fields?.issuetype?.name || ''))
  .map((i) => `${i.key}: ${i.fields?.summary || ''}\n${adfToText(i.fields?.description).trim()}`)
  .join('\n\n')
  .slice(0, 12000);
return [{ json: { ...plan, background } }];

// Loop entry: first attempt, or a retry carrying the previous draft and what to fix.
const s = $input.first().json;
return [{
  json: {
    ...s,
    background: s.background || '',
    attempt: (s.attempt || 0) + 1,
    candidate: s.candidate || '',
    feedback: s.feedback || '',
  },
}];

