// ---- helpers ----
function getLlmText(json) {
  // Works with the OpenAI "Message a model" node and most other model nodes.
  if (typeof json?.output === 'string') return json.output;
  if (Array.isArray(json?.output)) {
    for (const part of json.output) {
      if (Array.isArray(part?.content)) {
        const t = part.content.find((c) => c?.text != null);
        if (t) return typeof t.text === 'string' ? t.text : JSON.stringify(t.text); // JSON output mode returns an object
      }
    }
  }
  if (typeof json?.text === 'string') return json.text;
  if (typeof json?.content === 'string') return json.content;
  if (Array.isArray(json?.content)) {
    // Anthropic and similar: the text can come after a "thinking" block
    const t = json.content.find((c) => c?.type === 'text' && typeof c.text === 'string');
    if (t) return t.text;
  }
  if (typeof json?.merged_response === 'string' && json.merged_response) return json.merged_response;
  if (typeof json?.message?.content === 'string') return json.message.content;
  if (typeof json?.choices?.[0]?.message?.content === 'string') return json.choices[0].message.content;
  throw new Error('Could not find the text in the model response. Check the model node output.');
}
// ---- end helpers ----

// Hard rules checked by code, so a confident-sounding but broken table never reaches Jira.
const state = $('Next attempt').item.json;
let text = '';
try { text = getLlmText($json); } catch (e) { text = ''; }

const errors = [];
const lines = text.split('\n').map((l) => l.trim()).filter((l) => l.startsWith('|'));
const cells = (line) => line.replace(/^\|/, '').replace(/\|$/, '').split('|').map((c) => c.trim());
const expectedHeader = ['step #', 'action', 'data (optional)', 'expected result', 'stp section'];

let steps = [];
if (lines.length < 3) {
  errors.push('Return one markdown table with a header row, a separator row and at least one step.');
} else {
  const header = cells(lines[0]).map((c) => c.toLowerCase());
  if (header.join('|') !== expectedHeader.join('|')) {
    errors.push('The header must be exactly: | Step # | Action | Data (optional) | Expected Result | STP Section |');
  }
  steps = lines.slice(2).map(cells).map((c, i) => {
    if (c.length !== 5) errors.push(`Row ${i + 1} has ${c.length} columns instead of 5.`);
    return { action: c[1] || '', data: c[2] || '', result: c[3] || '', section: c[4] || '' };
  });
  steps.forEach((s, i) => {
    if (!s.action) errors.push(`Step ${i + 1} has no action.`);
    if (!s.result) errors.push(`Step ${i + 1} has no expected result.`);
  });
}
if (/assumption:/i.test(text)) errors.push('Remove every "Assumption:" text.');

const sections = steps.map((s) => s.section).filter(Boolean);
const bad = sections.filter((s) => !/^STP section \d+$/i.test(s));
if (bad.length) errors.push(`STP Section values must look exactly like "STP section 3". Wrong: ${bad.join(', ')}`);
const nums = sections.filter((s) => /^STP section \d+$/i.test(s)).map((s) => Number(s.match(/\d+/)[0]));
const dupes = nums.filter((n, i) => nums.indexOf(n) !== i);
if (dupes.length) errors.push(`Each STP section may appear only once. Repeated: ${[...new Set(dupes)].join(', ')}`);

// If the plan has a "Test Name" coverage table (as made by "AI Test Plan Generator"), every row must be covered.
if (state.expectedSections > 0) {
  const missing = [];
  for (let n = 1; n <= state.expectedSections; n++) if (!nums.includes(n)) missing.push(n);
  if (missing.length) errors.push(`The test plan lists ${state.expectedSections} tests. Missing STP sections: ${missing.join(', ')}`);
  const extra = nums.filter((n) => n > state.expectedSections);
  if (extra.length) errors.push(`STP sections ${extra.join(', ')} do not exist in the test plan.`);
}

return { json: { ...state, candidate: text, steps, formatOk: errors.length === 0, feedback: errors.map((e) => `- ${e}`).join('\n') } };

// ---- helpers ----
function getLlmText(json) {
  // Works with the OpenAI "Message a model" node and most other model nodes.
  if (typeof json?.output === 'string') return json.output;
  if (Array.isArray(json?.output)) {
    for (const part of json.output) {
      if (Array.isArray(part?.content)) {
        const t = part.content.find((c) => c?.text != null);
        if (t) return typeof t.text === 'string' ? t.text : JSON.stringify(t.text); // JSON output mode returns an object
      }
    }
  }
  if (typeof json?.text === 'string') return json.text;
  if (typeof json?.content === 'string') return json.content;
  if (Array.isArray(json?.content)) {
    // Anthropic and similar: the text can come after a "thinking" block
    const t = json.content.find((c) => c?.type === 'text' && typeof c.text === 'string');
    if (t) return t.text;
  }
  if (typeof json?.merged_response === 'string' && json.merged_response) return json.merged_response;
  if (typeof json?.message?.content === 'string') return json.message.content;
  if (typeof json?.choices?.[0]?.message?.content === 'string') return json.choices[0].message.content;
  throw new Error('Could not find the text in the model response. Check the model node output.');
}
// ---- end helpers ----

const state = $('Check format').item.json;
let review = '';
try { review = getLlmText($json).trim(); } catch (e) { review = ''; }
const passed = /^pass\b/i.test(review);
const fixes = review.replace(/^fail\b[:.]?/i, '').trim();
return { json: { ...state, reviewPassed: passed, feedback: passed ? '' : (fixes || '- The reviewer rejected the test case without details. Re-check every rule.') } };

const cfg = $('⚙️ Config').first().json;
const s = $input.first().json;
return [{ json: { ...s, giveUp: s.attempt >= cfg.maxAttempts } }];

const cfg = $('⚙️ Config').first().json;
const s = $input.first().json;
const name = s.summary.replace(/^test plan:\s*/i, '').replace(/^\(stp\)\s*/i, '');
const planUrl = `${cfg.jiraBaseUrl}/browse/${s.key}`;
const t = (x, marks) => (marks ? { type: 'text', text: String(x), marks } : { type: 'text', text: String(x || ' ') });
const para = (...c) => ({ type: 'paragraph', content: c });
const cell = (x, header = false) => ({ type: header ? 'tableHeader' : 'tableCell', attrs: {}, content: [para(t(x))] });

const content = [para(t('Generated from test plan '), t(s.key, [{ type: 'link', attrs: { href: planUrl } }]), t(`. Passed code checks and review on attempt ${s.attempt}.`))];
if (cfg.testManagement !== 'xray') {
  content.push({
    type: 'table', attrs: { isNumberColumnEnabled: false, layout: 'default' },
    content: [
      { type: 'tableRow', content: ['Step', 'Action', 'Data', 'Expected Result', 'STP Section'].map((h) => cell(h, true)) },
      ...s.steps.map((st, i) => ({ type: 'tableRow', content: [String(i + 1), st.action, st.data, st.result, st.section].map((x) => cell(x)) })),
    ],
  });
}

return [{
  json: {
    ...s,
    createBody: {
      fields: {
        project: { key: cfg.test.projectKey },
        issuetype: { name: cfg.test.issueType },
        summary: (cfg.test.summaryPrefix + name).slice(0, 254),
        description: { type: 'doc', version: 1, content },
      },
    },
  },
}];

const s = $('Build test issue').first().json;
const created = $('Create test issue').first().json;
const token = String($input.first().json.data ?? '').trim().replace(/^"|"$/g, '');
if (!token) throw new Error('Xray did not return a token. Check the Xray API key credential and xrayBaseUrl.');
return s.steps.map((st) => ({
  json: {
    token,
    issueId: String(created.id),
    action: st.action,
    data: st.data,
    result: st.result + (st.section ? `\n\n_${st.section}_` : ''),
  },
}));

const failed = $input.all().filter((i) => Array.isArray(i.json.errors) && i.json.errors.length);
if (failed.length) {
  throw new Error('Xray rejected some steps: ' + failed.map((i) => i.json.errors.map((e) => e.message).join('; ')).join(' | '));
}
return [{ json: { stepsAdded: $input.all().length } }];

// Finds the transition that leads to the configured status NAME.
const key = $('Create test issue').first().json.key;
const target = String($('⚙️ Config').first().json.test.statusAfterCreate).trim();
const list = $json.transitions || [];
const hit = list.find((t) => (t.to?.name || '').toLowerCase() === target.toLowerCase())
  || list.find((t) => (t.name || '').toLowerCase() === target.toLowerCase());
if (!hit) {
  const reachable = list.map((t) => t.to?.name).filter(Boolean).join(', ') || 'none';
  throw new Error(`Can't move ${key} to "${target}": not reachable from its current status (reachable: ${reachable}). Check the status name in ⚙️ Config.`);
}
return { json: { key, transitionId: hit.id, status: hit.to?.name || target } };

